package org.springframework.samples.petclinic.service;

import java.time.LocalDate;
import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Enforces the per-day owner cap: creation is blocked once
 * {@value #MAX_OWNERS_PER_DAY} owners already share today's registration date.
 */
public final class DailyRegistrationLimit {

    public static final int MAX_OWNERS_PER_DAY = 100;

    private DailyRegistrationLimit() {
    }

    public static boolean isReached(Collection<Owner> existing) {
        LocalDate today = LocalDate.now();
        long createdToday = existing.stream().filter(o -> today.equals(o.getRegistrationDate())).count();
        return createdToday >= MAX_OWNERS_PER_DAY;
    }
}

